provenance.steps_response:
[
  {
    "description": "Configure IPv6 addressing on the DUT's management/transit interface and enable the SSH server. Verify from an IPv6-capable client that the DUT is reachable over IPv6 and that a listener is present on the standard SSH port for the IPv6 address family.",
    "expectedResult": ""
  },
  {
    "description": "Open SSH sessions to the DUT from the client using each supported form of IPv6 destination address in turn — global unicast, link-local with the appropriate scope/zone identifier, and loopback where the platform supports it. Verify each form establishes a session.",
    "expectedResult": ""
  },
  {
    "description": "Authenticate over IPv6 with a valid username and password. Verify an interactive shell is granted at the expected privilege level and that the session is usable at the CLI prompt.",
    "expectedResult": ""
  },
  {
    "description": "Issue a representative range of CLI commands over the IPv6 SSH session, including commands producing long, paged and multi-line output. Compare the returned output against the same commands issued over an IPv4 SSH session or the console, and verify equivalence with no truncation or corruption.",
    "expectedResult": ""
  },
  {
    "description": "With the SSH server enabled, establish sessions over IPv4 and IPv6 at the same time from separate clients. Verify both address families are served concurrently, that each session operates independently, and that activity on one does not disturb the other.",
    "expectedResult": ""
  },
  {
    "description": "Populate the SSH server's allowed-user configuration and attempt IPv6 logins as each listed user. Verify the permitted users authenticate and reach the CLI.",
    "expectedResult": ""
  },
  {
    "description": "Attempt IPv6 logins as users that are explicitly denied and as users absent from the SSH server user configuration. Verify each attempt is rejected with the connection refused or closed and no CLI access granted.",
    "expectedResult": ""
  },
  {
    "description": "Drive failed authentications over IPv6 covering a valid user with an incorrect password, an unknown username, and a disabled or expired account. Repeat attempts to exercise the configured retry limit and any lockout behaviour, then verify no partial access is granted at any point and that recovery after lockout expiry behaves as configured.",
    "expectedResult": ""
  },
  {
    "description": "Open concurrent IPv6 SSH sessions from multiple clients or multiple users up to the configured maximum session limit. Verify every session stays independent and that the DUT attributes each to its own username and source IPv6 address.",
    "expectedResult": ""
  },
  {
    "description": "With the maximum number of IPv6 SSH sessions already established, attempt a further connection. Verify the attempt is refused or queued according to the product design and that the pre-existing sessions remain usable and unaffected.",
    "expectedResult": ""
  },
  {
    "description": "From an administrative session, terminate one of the active remote IPv6 SSH sessions by its session identifier. Verify the targeted session closes immediately on the client side, its resources are released on the DUT, and all other sessions — IPv4 and IPv6 — continue uninterrupted.",
    "expectedResult": ""
  },
  {
    "description": "Disable the SSH server while IPv6 sessions are active. Verify the existing sessions are handled deterministically per product design, that no listener remains on the SSH port for IPv6, that fresh IPv6 connection attempts are refused, and that the DUT remains stable.",
    "expectedResult": ""
  },
  {
    "description": "Re-enable the SSH server without restarting the device and verify new IPv6 sessions can be established and authenticated as before.",
    "expectedResult": ""
  },
  {
    "description": "Exercise invalid and unsupported connection conditions from the client over IPv6: malformed or incomplete IPv6 destination addresses, an unreachable IPv6 destination, a link-local address given with a missing or mismatched scope identifier, an unsupported cipher or key exchange algorithm, and an unsupported SSH protocol version. Verify each is rejected cleanly and that the DUT shows no crash, exception trace, hang or resource leak.",
    "expectedResult": ""
  },
  {
    "description": "Save the configuration with the SSH server enabled, the IPv6 listener active and the allow/deny user lists populated, then restart the device. Verify the SSH server state, IPv6 listener and user configuration are restored and that IPv6 logins behave as before the restart.",
    "expectedResult": ""
  },
  {
    "description": "With IPv6 sessions established, inspect the SSH server operational status. Verify it reports the server state, the address families being listened on, and an active session list showing source IPv6 addresses, usernames and session identifiers that match the sessions actually open.",
    "expectedResult": ""
  },
  {
    "description": "Review the DUT's log output after exercising IPv6 session establishment, successful and failed authentication, administrative session termination, and SSH server enable and disable transitions. Verify each event is recorded with an accurate timestamp and the correct source IPv6 address.",
    "expectedResult": ""
  },
  {
    "description": "Repeat a cycle of IPv6 SSH connect, authenticate, command execution and disconnect many times, mixing valid and failed authentications. Verify sessions continue to be served throughout and that the DUT shows no accumulating memory, session or file-descriptor usage, no exception traces and no degradation after the final cycle.",
    "expectedResult": ""
  }
]

